import React, { useState, useEffect } from 'react';
import { 
  Card, Select, Button, Alert, Spin, Typography, Space, Tag, Tabs, 
  Table, Switch, Tooltip, Descriptions, Statistic, Row, Col, Divider,
  Modal, Form, Input, InputNumber, message, Badge
} from 'antd';
import { 
  SettingOutlined, CheckCircleOutlined, ExclamationCircleOutlined,
  RobotOutlined, FunctionOutlined, UserOutlined, EyeOutlined,
  EditOutlined, SaveOutlined, PlusOutlined, InfoCircleOutlined,
  ThunderboltOutlined, DollarOutlined, ClockCircleOutlined,
  ApiOutlined, BulbOutlined, CodeOutlined
} from '@ant-design/icons';

const { Title, Text, Paragraph } = Typography;
const { Option } = Select;
const { TabPane } = Tabs;

// CSS стили для исправления видимости текста в Select
const selectStyles = `
.llm-select .ant-select-selector {
  color: var(--text-primary) !important;
  background: var(--bg-card) !important;
  border-color: var(--border-color) !important;
}

.llm-select .ant-select-selection-item {
  color: var(--text-primary) !important;
}

.llm-select .ant-select-selection-placeholder {
  color: var(--text-secondary) !important;
}

.llm-select.ant-select-focused .ant-select-selector {
  border-color: #1890ff !important;
  box-shadow: 0 0 0 2px rgba(24, 144, 255, 0.2) !important;
}
`;

// ===== INTERFACES =====

interface LLMModel {
  id: number;
  provider: string;
  model_name: string;
  display_name: string;
  description?: string;
  max_context_tokens: number;
  max_output_tokens: number;
  cost_per_input_token?: number;
  cost_per_output_token?: number;
  is_active: boolean;
  is_available: boolean;
  api_url?: string;
}

interface LLMFunctionConfig {
  id: number;
  function_name: string;
  display_name: string;
  description?: string;
  llm_model_id?: number;
  provider_override?: string;
  model_override?: string;
  is_enabled: boolean;
  settings_json?: string;
  llm_model?: LLMModel;
}

interface UserLLMPreferences {
  id: number;
  user_id: number;
  preferred_llm_model_id?: number;
  function_overrides_json?: string;
  preferred_llm_model?: LLMModel;
}

interface LLMSystemOverview {
  models: LLMModel[];
  functions: LLMFunctionConfig[];
  user_preferences?: UserLLMPreferences;
  system_info: {
    current_provider: string;
    available_providers: string[];
    is_configured: boolean;
  };
}

const LLMSettings: React.FC = () => {
  // ===== STATE =====
  const [overview, setOverview] = useState<LLMSystemOverview | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState('models');
  const [savingFunction, setSavingFunction] = useState<string | null>(null);
  const [savingPreferences, setSavingPreferences] = useState(false);
  const [chatPipelineJson, setChatPipelineJson] = useState<string>('');
  const [chatPipelineValid, setChatPipelineValid] = useState<boolean>(true);
  
  // Инъекция стилей для исправления видимости текста
  useEffect(() => {
    const styleId = 'llm-select-styles';
    if (!document.getElementById(styleId)) {
      const style = document.createElement('style');
      style.id = styleId;
      style.textContent = selectStyles;
      document.head.appendChild(style);
    }
    
    return () => {
      const existingStyle = document.getElementById(styleId);
      if (existingStyle) {
        existingStyle.remove();
      }
    };
  }, []);

  // ===== FETCH DATA =====
  const fetchOverview = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/llm/overview');
      if (response.ok) {
        const data: LLMSystemOverview = await response.json();
        setOverview(data);
        // Инициализируем форму пайплайна из функции chat
        const chatFunc = data.functions.find(f => f.function_name === 'chat');
        let initial = {
          history_recent_ratio: 0.3,
          use_emotion_weights: true,
          reserved_tokens: 2000,
          include_unified_analysis: true,
          include_reminders: true
        } as any;
        try {
          if (chatFunc?.settings_json) {
            const parsed = JSON.parse(chatFunc.settings_json);
            initial = { ...initial, ...parsed };
          }
        } catch {}
        setChatPipelineJson(JSON.stringify(initial, null, 2));
        setChatPipelineValid(true);
        setError(null);
      } else {
        setError('Ошибка загрузки данных LLM');
      }
    } catch (err) {
      setError('Ошибка сети при загрузке данных');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchOverview();
  }, []);

  // ===== UPDATE FUNCTIONS =====
  const updateFunctionConfig = async (functionName: string, config: Partial<LLMFunctionConfig>) => {
    try {
      setSavingFunction(functionName);
      const response = await fetch(`/api/llm/functions/${functionName}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(config),
      });

      if (response.ok) {
        message.success('Настройки функции обновлены');
        await fetchOverview();
      } else {
        const errorData = await response.json();
        message.error(`Ошибка обновления: ${errorData.detail}`);
      }
    } catch (err) {
      message.error('Ошибка сети при обновлении');
    } finally {
      setSavingFunction(null);
    }
  };

  const updateUserPreferences = async (preferences: Partial<UserLLMPreferences>) => {
    try {
      setSavingPreferences(true);
      // P23/P22: основной путь /api/llm/user/preferences, с безопасным фолбеком на dev-алиас
      let response = await fetch('/api/llm/user/preferences', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(preferences),
      });
      if (!response.ok) {
        // fallback для старых окружений
        response = await fetch('/api/llm/dev/user/preferences', {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(preferences),
        });
      }
      if (response.ok) {
        message.success('Пользовательские настройки обновлены');
        await fetchOverview();
      } else {
        const errorData = await response.json();
        message.error(`Ошибка обновления: ${errorData.detail}`);
      }
    } catch (err) {
      message.error('Ошибка сети при обновлении');
    } finally {
      setSavingPreferences(false);
    }
  };

  const saveChatPipeline = async () => {
    if (!overview) return;
    // Валидация JSON
    try {
      const parsed = JSON.parse(chatPipelineJson);
      setChatPipelineValid(true);
      setSavingFunction('chat');
      const response = await fetch(`/api/llm/functions/chat`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ settings_json: JSON.stringify(parsed) }),
      });
      if (response.ok) {
        message.success('Конфигурация пайплайна чата сохранена');
        await fetchOverview();
      } else {
        const errorData = await response.json();
        message.error(`Ошибка сохранения: ${errorData.detail}`);
      }
    } catch (e) {
      setChatPipelineValid(false);
      message.error('Неверный JSON. Исправьте ошибки.');
    } finally {
      setSavingFunction(null);
    }
  };

  // ===== UTILITY FUNCTIONS =====
  const getProviderColor = (provider: string) => {
    const colors: Record<string, string> = {
      'deepseek': 'purple',
      'openai': 'blue',
      'gigachat': 'green'
    };
    return colors[provider] || 'default';
  };

  const getProviderIcon = (provider: string) => {
    switch (provider) {
      case 'deepseek': return '🧠';
      case 'openai': return '🤖';
      case 'gigachat': return '🇷🇺';
      default: return '🔧';
    }
  };

  const formatCost = (cost?: number) => {
    if (!cost) return 'Бесплатно';
    return `$${(cost * 1000000).toFixed(2)}/1M токенов`;
  };

  // ===== RENDER MODELS TAB =====
  const renderModelsTab = () => {
    if (!overview) return null;

    const columns = [
      {
        title: 'Модель',
        key: 'model',
        render: (model: LLMModel) => (
          <Space>
            <span style={{ fontSize: '18px' }}>{getProviderIcon(model.provider)}</span>
            <div>
              <div style={{ fontWeight: 'bold' }}>{model.display_name}</div>
              <Text type="secondary" style={{ fontSize: '12px' }}>
                {model.provider} / {model.model_name}
              </Text>
            </div>
          </Space>
        ),
      },
      {
        title: 'Описание',
        dataIndex: 'description',
        key: 'description',
        width: '40%',
        render: (desc: string) => (
          <Text style={{ fontSize: '13px', lineHeight: 1.4 }}>
            {desc || 'Нет описания'}
          </Text>
        ),
      },
      {
        title: 'Контекст',
        key: 'context',
        render: (model: LLMModel) => (
          <Space direction="vertical" size="small">
            <div>
              <ClockCircleOutlined style={{ marginRight: 4 }} />
              <Text style={{ fontSize: '12px' }}>
                {(model.max_context_tokens / 1000).toFixed(0)}K входящих
              </Text>
            </div>
            <div>
              <ThunderboltOutlined style={{ marginRight: 4 }} />
              <Text style={{ fontSize: '12px' }}>
                {(model.max_output_tokens / 1000).toFixed(0)}K исходящих
              </Text>
            </div>
          </Space>
        ),
      },
      {
        title: 'Стоимость',
        key: 'cost',
        render: (model: LLMModel) => (
          <Space direction="vertical" size="small">
            <div>
              <Text style={{ fontSize: '11px' }}>Вход: {formatCost(model.cost_per_input_token)}</Text>
            </div>
            <div>
              <Text style={{ fontSize: '11px' }}>Выход: {formatCost(model.cost_per_output_token)}</Text>
            </div>
          </Space>
        ),
      },
      {
        title: 'Статус',
        key: 'status',
        render: (model: LLMModel) => (
          <Space direction="vertical" size="small">
            <Tag color={model.is_available ? 'green' : 'red'}>
              {model.is_available ? 'Доступна' : 'Недоступна'}
            </Tag>
            <Tag color={model.is_active ? 'blue' : 'default'}>
              {model.is_active ? 'Активна' : 'Неактивна'}
            </Tag>
          </Space>
        ),
      },
    ];

    return (
      <Card title={
        <Space>
          <RobotOutlined />
          <span>LLM Модели</span>
          <Badge count={overview.models.length} style={{ backgroundColor: '#52c41a' }} />
        </Space>
      }>
        <Table
          dataSource={overview.models}
          columns={columns}
          rowKey="id"
          pagination={false}
          size="small"
        />
      </Card>
    );
  };

  // ===== RENDER FUNCTIONS TAB =====
  const renderFunctionsTab = () => {
    if (!overview) return null;

    const columns = [
      {
        title: 'Функция',
        key: 'function',
        render: (func: LLMFunctionConfig) => (
          <Space>
            <div>
              <div style={{ fontWeight: 'bold' }}>{func.display_name}</div>
              <Text type="secondary" style={{ fontSize: '12px' }}>
                {func.function_name}
              </Text>
            </div>
          </Space>
        ),
      },
      {
        title: 'Описание',
        dataIndex: 'description',
        key: 'description',
        render: (desc: string) => (
          <Text style={{ fontSize: '13px' }}>{desc || 'Нет описания'}</Text>
        ),
      },
      {
        title: 'Текущая модель',
        key: 'current_model',
        render: (func: LLMFunctionConfig) => {
          const model = func.llm_model;
          if (model) {
            return (
              <Space>
                <span>{getProviderIcon(model.provider)}</span>
                <Text>{model.display_name}</Text>
              </Space>
            );
          }
          return (
            <Tag color="orange">
              <ApiOutlined style={{ marginRight: 4 }} />
              Системная настройка
            </Tag>
          );
        },
      },
      {
        title: 'Включена',
        key: 'enabled',
        render: (func: LLMFunctionConfig) => (
          <Switch
            checked={func.is_enabled}
            loading={savingFunction === func.function_name}
            onChange={(enabled) => updateFunctionConfig(func.function_name, { is_enabled: enabled })}
          />
        ),
      },
      {
        title: 'Модель',
        key: 'model_select',
        render: (func: LLMFunctionConfig) => (
          <Select
            style={{ 
              width: 200
            }}
            dropdownStyle={{
              background: 'var(--bg-card)',
              border: '1px solid var(--border-color)'
            }}
            className="llm-select"
            value={func.llm_model_id || undefined}
            placeholder="Выберите модель"
            allowClear
            loading={savingFunction === func.function_name}
            onChange={(modelId) => updateFunctionConfig(func.function_name, { llm_model_id: modelId })}
          >
            <Option value={undefined}>
              <Space style={{ color: 'var(--text-primary)' }}>
                <ApiOutlined style={{ color: 'var(--text-secondary)' }} />
                <span style={{ color: 'var(--text-primary)' }}>Системная настройка</span>
              </Space>
            </Option>
            {overview.models
              .filter(m => m.is_available)
              .map(model => (
                <Option key={model.id} value={model.id}>
                  <Space style={{ color: 'var(--text-primary)' }}>
                    <span>{getProviderIcon(model.provider)}</span>
                    <span style={{ color: 'var(--text-primary)' }}>{model.display_name}</span>
                  </Space>
                </Option>
              ))
            }
          </Select>
        ),
      },
    ];

    return (
      <Card title={
        <Space>
          <FunctionOutlined />
          <span>Функции системы</span>
          <Badge count={overview.functions.length} style={{ backgroundColor: '#1890ff' }} />
        </Space>
      }>
        <Table
          dataSource={overview.functions}
          columns={columns}
          rowKey="id"
          pagination={false}
          size="small"
        />
      </Card>
    );
  };

  // ===== RENDER CHAT PIPELINE TAB =====
  const renderChatPipelineTab = () => {
    const helper = (
      <Alert
        type="info"
        showIcon
        message="Параметры пайплайна чата"
        description={
          <div>
            <div>history_recent_ratio: доля последних сообщений в истории (0..1)</div>
            <div>use_emotion_weights: учитывать веса эмоций при выборе истории</div>
            <div>reserved_tokens: резерв токенов под ответ</div>
            <div>include_unified_analysis: включать структурированный анализ</div>
            <div>include_reminders: извлекать напоминания (§svc)</div>
          </div>
        }
        style={{ marginBottom: 12 }}
      />
    );
    return (
      <Space direction="vertical" style={{ width: '100%' }}>
        {helper}
        <Card title={<Space><CodeOutlined /> <span>JSON-конфигурация</span></Space>}>
          <Input.TextArea
            value={chatPipelineJson}
            onChange={(e) => setChatPipelineJson(e.target.value)}
            autoSize={{ minRows: 14, maxRows: 24 }}
            status={chatPipelineValid ? undefined : 'error'}
          />
          <div style={{ marginTop: 12, textAlign: 'right' }}>
            <Button
              type="primary"
              icon={<SaveOutlined />}
              loading={savingFunction === 'chat'}
              onClick={saveChatPipeline}
            >
              Сохранить
            </Button>
          </div>
        </Card>
      </Space>
    );
  };

  // ===== RENDER USER TAB =====
  const renderUserTab = () => {
    if (!overview) return null;

    const userPrefs = overview.user_preferences;
    const globalModel = userPrefs?.preferred_llm_model;

    return (
      <Space direction="vertical" style={{ width: '100%' }} size="large">
        <Card title={
          <Space>
            <UserOutlined />
            <span>Ваши настройки LLM</span>
          </Space>
        }>
          <Row gutter={[16, 16]}>
            <Col xs={24} md={12}>
              <Card size="small" title="Глобальная модель">
                <Space direction="vertical" style={{ width: '100%' }}>
                  <Text type="secondary">
                    Модель по умолчанию для всех функций
                  </Text>
                  <Select
                    style={{ 
                      width: '100%'
                    }}
                    dropdownStyle={{
                      background: 'var(--bg-card)',
                      border: '1px solid var(--border-color)'
                    }}
                    className="llm-select"
                    value={userPrefs?.preferred_llm_model_id || undefined}
                    placeholder="Выберите глобальную модель"
                    allowClear
                    loading={savingPreferences}
                    onChange={(modelId) => updateUserPreferences({ preferred_llm_model_id: modelId })}
                  >
                    <Option value={undefined}>
                      <Space style={{ color: 'var(--text-primary)' }}>
                        <ApiOutlined style={{ color: 'var(--text-secondary)' }} />
                        <span style={{ color: 'var(--text-primary)' }}>Системная настройка</span>
                      </Space>
                    </Option>
                    {overview.models
                      .filter(m => m.is_available)
                      .map(model => (
                        <Option key={model.id} value={model.id}>
                          <Space style={{ color: 'var(--text-primary)' }}>
                            <span>{getProviderIcon(model.provider)}</span>
                            <span style={{ color: 'var(--text-primary)' }}>{model.display_name}</span>
                          </Space>
                        </Option>
                      ))
                    }
                  </Select>
                  
                  {globalModel && (
                    <div style={{ marginTop: 16, padding: 12, background: '#f0f2f5', borderRadius: 8 }}>
                      <Space direction="vertical" size="small">
                        <div>
                          <Text strong>Выбрана: {globalModel.display_name}</Text>
                        </div>
                        <div>
                          <Text type="secondary" style={{ fontSize: '12px' }}>
                            {globalModel.description}
                          </Text>
                        </div>
                        <div>
                          <Space>
                            <Tag color={getProviderColor(globalModel.provider)}>
                              {globalModel.provider}
                            </Tag>
                            <Text style={{ fontSize: '11px' }}>
                              {(globalModel.max_context_tokens / 1000).toFixed(0)}K токенов
                            </Text>
                          </Space>
                        </div>
                      </Space>
                    </div>
                  )}
                </Space>
              </Card>
            </Col>
            
            <Col xs={24} md={12}>
              <Card size="small" title="Статистика использования">
                <Row gutter={16}>
                  <Col span={12}>
                    <Statistic
                      title="Функций настроено"
                      value={overview.functions.filter(f => f.llm_model_id).length}
                      suffix={`/ ${overview.functions.length}`}
                    />
                  </Col>
                  <Col span={12}>
                    <Statistic
                      title="Доступно моделей"
                      value={overview.models.filter(m => m.is_available).length}
                      suffix={`/ ${overview.models.length}`}
                    />
                  </Col>
                </Row>
              </Card>
            </Col>
          </Row>
        </Card>

        <Card title="Системная информация" size="small">
          <Descriptions size="small" column={2}>
            <Descriptions.Item label="Текущий провайдер">
              <Space>
                <span>{getProviderIcon(overview.system_info.current_provider)}</span>
                <Tag color={getProviderColor(overview.system_info.current_provider)}>
                  {overview.system_info.current_provider}
                </Tag>
                {overview.system_info.is_configured && (
                  <CheckCircleOutlined style={{ color: '#52c41a' }} />
                )}
              </Space>
            </Descriptions.Item>
            <Descriptions.Item label="Доступные провайдеры">
              <Space>
                {overview.system_info.available_providers.map(provider => (
                  <Tag key={provider} color={getProviderColor(provider)}>
                    {getProviderIcon(provider)} {provider}
                  </Tag>
                ))}
              </Space>
            </Descriptions.Item>
            <Descriptions.Item label="Состояние" span={2}>
              <Tag color={overview.system_info.is_configured ? 'green' : 'red'}>
                {overview.system_info.is_configured ? 'Настроен' : 'Требует настройки'}
              </Tag>
            </Descriptions.Item>
          </Descriptions>
        </Card>
      </Space>
    );
  };

  // ===== MAIN RENDER =====
  if (loading) {
    return (
      <Card>
        <div style={{ textAlign: 'center', padding: 'var(--sp-spacing-md, 40px)', boxSizing: 'border-box', maxWidth: '100%' }}>
          <Spin size="large" />
          <div style={{ marginTop: 'var(--sp-spacing-sm)' }}>
            <Title level={4}>Загрузка LLM системы...</Title>
            <Text type="secondary">Получение информации о моделях и настройках</Text>
          </div>
        </div>
      </Card>
    );
  }

  if (error) {
    return (
      <Card>
        <Alert
          message="Ошибка загрузки"
          description={error}
          type="error"
          showIcon
          action={
            <Button size="small" onClick={fetchOverview}>
              Повторить
            </Button>
          }
        />
      </Card>
    );
  }

  if (!overview) {
    return (
      <Card>
        <Alert
          message="Нет данных"
          description="Не удалось загрузить информацию о LLM системе"
          type="warning"
          showIcon
        />
      </Card>
    );
  }

  return (
    <div style={{ padding: 'var(--sp-spacing-sm)', boxSizing: 'border-box', maxWidth: '100%' }}>
      <div style={{ marginBottom: 'var(--sp-spacing-sm)' }}>
        <Title level={2}>
          <SettingOutlined style={{ marginRight: 8 }} />
          Управление LLM моделями
        </Title>
        <Paragraph type="secondary">
          Настройка моделей искусственного интеллекта и их распределение по функциям системы
        </Paragraph>
      </div>

      <Tabs
        activeKey={activeTab}
        onChange={setActiveTab}
        type="card"
        size="large"
      >
        <TabPane
          tab={
            <Space>
              <RobotOutlined />
              <span>Модели</span>
              <Badge count={overview.models.length} style={{ backgroundColor: '#52c41a' }} />
            </Space>
          }
          key="models"
        >
          {renderModelsTab()}
        </TabPane>

        <TabPane
          tab={
            <Space>
              <FunctionOutlined />
              <span>Функции</span>
              <Badge count={overview.functions.length} style={{ backgroundColor: '#1890ff' }} />
            </Space>
          }
          key="functions"
        >
          {renderFunctionsTab()}
        </TabPane>

        <TabPane
          tab={
            <Space>
              <CodeOutlined />
              <span>Пайплайн чата</span>
            </Space>
          }
          key="chat_pipeline"
        >
          {renderChatPipelineTab()}
        </TabPane>

        <TabPane
          tab={
            <Space>
              <UserOutlined />
              <span>Мои настройки</span>
            </Space>
          }
          key="user"
        >
          {renderUserTab()}
        </TabPane>
      </Tabs>
    </div>
  );
};

export default LLMSettings;